contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We receive Ether when C transfers to us during fallback execution on multiples of 15
    receive() external payable {}

    // Single public test entry point. amount must be provided by the caller and used to send value.
    function run(uint blockNumberMod15, uint amount) public payable {
        // require we have enough balance in this contract to forward `amount` to c
        require(address(this).balance >= amount, "insufficient balance");
        // We only care about the behavior when sending exactly 10 ether because C.requires that
        // amount may be arbitrary but the property will consider the case amount == 10 ether.

        // Read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // We must simulate being in a block where block.number % 15 has a certain value.
        // We cannot change block.number here; instead the property will be conditional:
        // If the call does not revert and we sent exactly 10 ether, then the invariants below must hold.

        bool reverted;
        // perform the call to C's fallback by sending Ether to it
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint ourBalance = address(this).balance;

        // Assert general rule: If we sent exactly 10 ether and the call did NOT revert,
        // then pastBlockTime strictly increases (afterPast > beforePast), and
        // if the current block number is divisible by 15 then C must have paid out its entire balance
        // (so its balance is 0 and our balance increased by that amount), otherwise C's balance
        // increased by exactly 10 ether.
        // We cannot directly read block.number here to make the conditional proven for all runs,
        // so express the rule in terms of the effect: either afterBalance == 0 (payout happened)
        // or afterBalance == beforeBalance + 10 ether (no payout). Also require the call didn't revert
        // when amount == 10 ether.

        assert(
            // only claim anything when the call succeeded and we sent exactly 10 ether
            (!(reverted) && amount == 10 ether) ?
                (
                    // pastBlockTime must strictly increase
                    (afterPast > beforePast)
                    // and balance is either drained to 0 (payout) or increased by exactly 10 ether
                    && ( (afterBalance == 0) || (afterBalance == beforeBalance + 10 ether) )
                )
                :
                // if call reverted or amount != 10 ether, no guarantee by this property
                true
        );
    }
}

