    // single public test function taking parameters: amount to send and a synthetic blockNumberModulo15 flag
    function run(uint amount, uint beforePastBlockTime, bool triggerPayout) public payable {
        require(amount == 10 ether, "must send exactly 10 ether to exercise fallback");
        // ensure this contract has enough balance to forward
        require(address(this).balance >= amount, "insufficient balance to forward");

        // Observe prior public pastBlockTime (the contract's getter)
        uint prev = c.pastBlockTime();

        // The test environment will set block.timestamp and block.number; we cannot set them here.
        // We attempt the call and capture whether it reverted.
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call (whether reverted or not), read observable values
        uint after = c.pastBlockTime();
        uint bal = address(c).balance;
        uint myBal = address(this).balance;

        // General rule asserted: if call succeeded, pastBlockTime strictly increased, and either
        // (a) if fallback payout condition (block.number % 15 == 0) held then contract balance is zero
        //     (payout sent to this test contract), otherwise contract balance increased by amount.
        // We cannot read block.number here; encode payout possibility via comparing balances:
        // If call succeeded and contract balance is < amount then payout happened (balance became zero),
        // else balance increased by amount relative to previous balance (which equals bal - (triggered ? prevBal : 0)).

        // To make a provable general assertion without reading previous contract balance directly,
        // we assert the invariant parts: when call succeeded, pastBlockTime > prev, and if reverted then pastBlockTime unchanged.
        assert(
            // If call reverted then pastBlockTime unchanged and balances unchanged
            (reverted && after == prev)
            ||
            // If call succeeded then pastBlockTime strictly increased by at least 1
            (!reverted && after > prev)
