contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters: amount to send (must be 10 ether to avoid immediate revert),
    // and a dummy parameter newCall to allow different inputs; block.timestamp and block.number
    // are environment values the verifier reasons about.
    function run(uint256 amount, uint256 /*newCall*/) public payable {
        require(address(this).balance >= amount, "insufficient balance to send");
        // only meaningful test if caller attempts to send exactly 10 ether to fallback
        // but we allow other amounts to exercise the revert path

        // read before-values
        uint256 beforePast = c.pastBlockTime();
        uint256 beforeBalanceC = address(c).balance;
        uint256 beforeBalanceThis = address(this).balance;

        bool reverted;
        // make the state-changing call: fallback is payable and will be invoked by sending to c
        // We must call it as low-level: call with empty data triggers fallback.
        // Use try/catch on (address).call to detect revert.
        (bool ok, ) = address(c).call{value: amount}("\x00");
        // Note: sending any non-empty data to fallback still triggers fallback; we use one byte.
        reverted = !ok;

        // read after-values
        uint256 afterPast = c.pastBlockTime();
        uint256 afterBalanceC = address(c).balance;
        uint256 afterBalanceThis = address(this).balance;

        // General rule to assert:
        // If the call reverted, no state of c changed (pastBlockTime and balance unchanged).
        // If the call did not revert and amount == 10 ether then:
        //   - pastBlockTime == block.timestamp + 1
        //   - if block.number % 15 == 0 then C forwarded its entire balance to msg.sender during the call,
        //     so afterBalanceThis == beforeBalanceThis + beforeBalanceC + 10 ether - (any gas costs are not tracked here because transfer uses transfer which forwards 2300 gas, but in this environment we model balances exactly), and afterBalanceC == 0.
        //   - otherwise, C's balance increased by exactly 10 ether and afterBalanceC == beforeBalanceC + 10 ether.

        // Encode the rule as a single assert over observed values and parameters.
        if (reverted) {
            assert(afterPast == beforePast && afterBalanceC == beforeBalanceC);
        } else {
            // call succeeded
            // require that amount was 10 ether (fallback requires this in contract C)
            // since call succeeded, amount must equal 10 ether; express as relation
            assert(amount == 10 ether);

            // pastBlockTime must have been updated to block.timestamp + 1
            assert(afterPast == block.timestamp + 1);

            // two cases depending on block.number % 15
            if (block.number % 15 == 0) {
                // when divisible, contract transfers its whole balance to msg.sender
                // after the call c's balance should be zero
                assert(afterBalanceC == 0);
                // and the test contract gained exactly beforeBalanceC + 10 ether
                assert(afterBalanceThis == beforeBalanceThis + beforeBalanceC + 10 ether);
            } else {
                // otherwise C keeps the 10 ether
                assert(afterBalanceC == beforeBalanceC + 10 ether);
                // and our balance decreased by exactly 10 ether
                assert(afterBalanceThis == beforeBalanceThis - 10 ether);
            }
        }
    }

    // allow receiving transferred Ether in case C transfers to this contract during the call
    receive() external payable {}
}

