    constructor(C _c) { c = _c; }

    // Call fallback by making a low-level call to address(c) with empty calldata and value `amount`.
    // Parameter: amount of wei to send to c.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // Perform the low-level call to trigger fallback and capture whether it reverted
        bool reverted;
        bytes memory ret;
        (reverted, ret) = _callFallback(amount);

        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // Assert the general rule described in the summary.
        // If call succeeded (not reverted): pastBlockTime increased by at least 1 and balance is either 0 (forwarded) or increased by exactly amount.
        // If reverted: then amount != 10 ether OR block.timestamp <= beforePast.
        assert(
            (!reverted) ? (
                (afterPast >= beforePast + 1) &&
                ((afterBal == 0) || (afterBal == beforeBal + amount))
            ) : (
                (amount != 10 ether) || (block.timestamp <= beforePast)
            )
        );
    }

    // Helper performing the low-level call; kept as an internal top-level-style operation returning revert flag.
    function _callFallback(uint amount) internal returns (bool, bytes memory) {
        // Make sure this contract has enough balance; checked by caller
        (bool ok, bytes memory data) = address(c).call{value: amount}("");
        return (!ok, data);
    }

    receive() external payable {}
}

