contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call the fallback by sending Ether to c. We cannot name the fallback, so use call syntax.
    // Parameters: amount to send (must be provided by caller), and a simulated currentBlockNumberModulo15 flag
    // The function is payable so the caller can fund this contract to forward funds to c.
    function run(uint amount, uint simulatedBlockNumber) public payable {
        // Precondition: we only want to attempt call when amount is at least 10 ether so we can send exactly 10 ether
        // and also ensure this contract has funds to forward.
        require(amount >= 10 ether);
        require(address(this).balance >= 10 ether);

        // Read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // We want to emulate two scenarios: when the fallback is called with exactly 10 ether.
        // The real block.number and block.timestamp are provided by EVM; tests that try to reason about
        // divisibility by 15 must account that we cannot set block.number here. Instead we use a conservative assertion:
        // If call succeeds, pastBlockTime must increase. Additionally, if block.number % 15 != 0 then contract should keep its funds;
        // if block.number % 15 == 0 then the caller (this) should receive the contract's balance after call.

        // Perform the call sending exactly 10 ether to trigger fallback
        bool reverted;
        // ensure we have the funds to send
        require(address(this).balance >= 10 ether);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        reverted = !ok;

        // Read after-values (always allowed even if call reverted)
        uint afterPast = c.pastBlockTime();
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        // The general rule asserted below:
        // If the call did not revert then (1) pastBlockTime strictly increased, and (2) either the contract kept its balance
        // (i.e. afterCBalance == beforeCBalance + 10 ether if no withdrawal happened) OR the test contract's balance increased by exactly beforeCBalance
        // (i.e. a full withdrawal happened when block.number % 15 == 0). We cannot directly read block.number here in the assertion,
        // so we assert the implication structure that for successful call one of these observable outcomes must hold.
        assert(
            reverted || (
                // call succeeded
                afterPast > beforePast
                && (
                    // Either no full withdrawal happened: contract retains what it had plus the 10 ether sent
                    (afterCBalance == beforeCBalance + 10 ether && afterThisBalance == beforeThisBalance - 10 ether)
                    ||
                    // Or a full withdrawal happened: contract balance is 0 and this contract gained exactly the previous contract balance
                    (afterCBalance == 0 && afterThisBalance == beforeThisBalance - 10 ether + beforeCBalance)
                )
            )
        );
    }

    // Allow receiving Ether when C sends refunds/withdrawals to this contract
    receive() external payable {}
}

