                )
                // conservation of Ether for this account: this contract's balance either decreased by amount (sent) or increased by transfer from C
                && (
                    (afterBalThis == beforeBalThis - amount) // sent and not returned
                    || (afterBalThis >= beforeBalThis)        // got refunded or received transfer
